BEGIN TRY BEGIN TRANSACTION;
INSERT cfg.Language(Code,Name) SELECT 'es',N'Spanish' WHERE NOT EXISTS(SELECT 1 FROM cfg.Language WHERE Code='es');
INSERT cfg.Language(Code,Name) SELECT 'ar',N'Arabic' WHERE NOT EXISTS(SELECT 1 FROM cfg.Language WHERE Code='ar');
INSERT cfg.LanguagePresentation(LanguageId,NativeName,Direction,IsInterfaceEnabled,FallbackLanguageId) SELECT l.Id,CASE l.Code WHEN 'ar' THEN N'العربية' WHEN 'es' THEN N'Español' ELSE N'English' END,CASE WHEN l.Code='ar' THEN 'rtl' ELSE 'ltr' END,1,CASE WHEN l.Code<>'en-IN' THEN (SELECT Id FROM cfg.Language WHERE Code='en-IN') END FROM cfg.Language l WHERE l.Code IN ('en-IN','es','ar') AND NOT EXISTS(SELECT 1 FROM cfg.LanguagePresentation p WHERE p.LanguageId=l.Id);
UPDATE cfg.Menu SET IsVisible=0 WHERE Code IN ('wealth','goals');
INSERT cfg.RouteAlias VALUES(N'/wealth',N'/money/financial-plan/assets-debts'),(N'/goals',N'/money/financial-plan/family-goals');
INSERT cfg.Menu(Code,ParentId,Label,Route,IconKey,PermissionId,SortOrder,BackgroundColor,ForegroundColor) SELECT 'money.financial-plan',Id,N'Financial plan','/money/financial-plan','wallet',PermissionId,1,'#235fe1','#ffffff' FROM cfg.Menu WHERE Code='money';
INSERT cfg.Menu(Code,ParentId,Label,Route,IconKey,PermissionId,SortOrder,BackgroundColor,ForegroundColor) SELECT 'money.tracker',Id,N'Daily tracker & budget','/money/tracker','wallet',PermissionId,2,'#235fe1','#ffffff' FROM cfg.Menu WHERE Code='money';
INSERT cfg.Menu(Code,ParentId,Label,Route,IconKey,PermissionId,SortOrder,BackgroundColor,ForegroundColor) SELECT 'money.records',Id,N'Sample financial records','/money/records','wallet',PermissionId,3,'#235fe1','#ffffff' FROM cfg.Menu WHERE Code='money';
INSERT cfg.Setting(Code,ValueJson,Description,IsPublic) VALUES('finance.plan.steps',N'{"steps":["Family & goals","Assets & debts","Monthly cash flow","Retirement","Retirement cash flow","Children’s goals","Emergency reserve","Protection","Plan report"]}',N'Guided financial planner sections inside Money & budget',1),('ui.language',N'{"default":"en-IN","choices":["en-IN","es","ar"],"fallback":"en-IN","contentStatus":"partial","expenseParserLanguage":"en"}',N'UI language does not change currency or translate entered medical content',1),('pantry.presentation',N'{"hero":["#123c9c","#245ee3"],"metrics":["#5035b7","#b65011","#08785e","#2053b4"],"imageFallback":"Photo not configured","imagesStatus":"pending"}',N'Bold pantry design; ingredient media is configured through food.Ingredient.MediaId',1);
