INSERT cfg.TextResource(ResourceKey,SourceText,ContextLabel) VALUES('ui.23b0a465f13d1d1b7fd588c7a92d7bb2',N'The prototype does not verify prescriptions, select doses or recommend substitutions. Prescription review and checkout happen with the pharmacy.',N'Wireframe interface');
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.23b0a465f13d1d1b7fd588c7a92d7bb2',N'The prototype does not verify prescriptions, select doses or recommend substitutions. Prescription review and checkout happen with the pharmacy.' FROM cfg.Language WHERE Code='en-IN';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.23b0a465f13d1d1b7fd588c7a92d7bb2',N'El prototipo no verifica recetas, elige dosis ni recomienda sustitutos. La farmacia revisa la receta y procesa la compra.' FROM cfg.Language WHERE Code='es';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.23b0a465f13d1d1b7fd588c7a92d7bb2',N'لا يتحقق النموذج من الوصفات ولا يحدد الجرعات أو يوصي ببدائل. تراجع الصيدلية الوصفة وتتم عملية الشراء لديها.' FROM cfg.Language WHERE Code='ar';
INSERT cfg.TextResource(ResourceKey,SourceText,ContextLabel) VALUES('ui.fdaeed1bb0df2158051965152c7bbacb',N'Use fictional details. This is a purchase checklist, not a prescription or dosing plan.',N'Wireframe interface');
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.fdaeed1bb0df2158051965152c7bbacb',N'Use fictional details. This is a purchase checklist, not a prescription or dosing plan.' FROM cfg.Language WHERE Code='en-IN';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.fdaeed1bb0df2158051965152c7bbacb',N'Usa datos ficticios. Es una lista de compra, no una receta ni una pauta de dosis.' FROM cfg.Language WHERE Code='es';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.fdaeed1bb0df2158051965152c7bbacb',N'استخدم بيانات افتراضية. هذه قائمة شراء وليست وصفة أو خطة جرعات.' FROM cfg.Language WHERE Code='ar';
INSERT cfg.TextResource(ResourceKey,SourceText,ContextLabel) VALUES('ui.36c4af67f767e33abcb23e22e67acc11',N'The file picker records a filename only. It does not upload to a pharmacy or retain file contents.',N'Wireframe interface');
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.36c4af67f767e33abcb23e22e67acc11',N'The file picker records a filename only. It does not upload to a pharmacy or retain file contents.' FROM cfg.Language WHERE Code='en-IN';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.36c4af67f767e33abcb23e22e67acc11',N'El selector registra solo el nombre del archivo. No lo envía ni conserva su contenido.' FROM cfg.Language WHERE Code='es';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.36c4af67f767e33abcb23e22e67acc11',N'يسجل منتقي الملفات اسم الملف فقط. لا يرفعه إلى الصيدلية ولا يحتفظ بمحتواه.' FROM cfg.Language WHERE Code='ar';
INSERT cfg.TextResource(ResourceKey,SourceText,ContextLabel) VALUES('ui.4e2e5b4016111906a0f59ff87354c985',N'Filename-only demonstration. No document is uploaded, read, saved or interpreted. Use a test file, not a real medical report.',N'Wireframe interface');
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.4e2e5b4016111906a0f59ff87354c985',N'Filename-only demonstration. No document is uploaded, read, saved or interpreted. Use a test file, not a real medical report.' FROM cfg.Language WHERE Code='en-IN';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.4e2e5b4016111906a0f59ff87354c985',N'Demostración del nombre del archivo. No se carga, lee, guarda ni interpreta ningún documento. Usa un archivo de prueba.' FROM cfg.Language WHERE Code='es';
INSERT cfg.Translation(LanguageId,ResourceKey,Text) SELECT Id,'ui.4e2e5b4016111906a0f59ff87354c985',N'عرض لاسم الملف فقط. لا تُرفع الوثيقة أو تُقرأ أو تُحفظ أو تُفسر. استخدم ملف اختبار.' FROM cfg.Language WHERE Code='ar';
INSERT cfg.TextResource(ResourceKey,SourceText,ContextLabel) VALUES('ui.4dfb799b35a361855bca70d2491e1a3a',N'Aarohi · Made for the way your family lives.',N'Wireframe interface');
