INSERT food.IngredientPresentation(IngredientId,CategoryCode,AccentColor,SortOrder) SELECT Id,CASE WHEN Code IN ('rice','lentils','ragi','atta','jowar','besan') THEN 'GrainsPulses' WHEN Code='yogurt' THEN 'Dairy' WHEN Code IN ('carrot','spinach','onion','tomato') THEN 'Vegetables' ELSE 'Other' END,CASE Code WHEN 'rice' THEN '#5e46d8' WHEN 'lentils' THEN '#da8310' WHEN 'ragi' THEN '#a5486d' WHEN 'carrot' THEN '#ea6b28' WHEN 'spinach' THEN '#13825a' WHEN 'yogurt' THEN '#2474c8' WHEN 'onion' THEN '#9552ad' WHEN 'tomato' THEN '#d74445' ELSE '#3165b6' END,Id FROM food.Ingredient;
